-- Venue Live Guest "Rustic Wedding". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara wedding), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'rustic-wedding', 'Rustic Wedding (panggung kayu)', 'wedding', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 125, 'center 38%',
  $t${"name":"Rustic Wedding","orn":"blossom","ui":{"ivory":"#FFF6EA","white":"#FFFFFF","soft":"#F6E3CF","soft2":"#E4BE9A","accent":"#A0603A","deep":"#4A2B18","ink":"#3B2416","mute":"#8A6F5C","line":"#EBD3BC","serif":"\"Cormorant Garamond\",serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Cormorant Garamond\",serif","it":0,"paper":"#FFF9F0","ink":"#3B2416","accent":"#A0603A","gold":"#C9964A","leaf":"#F3DCC4","hbg":"rgba(255,246,234,.94)","hline":"#E4BE9A","motif":"blossom"},"hud":{"bg":"rgba(74,43,24,.82)","acc":"#F5CFA0","on":"#3B2416"},"scr":{"wine":"#4A2B18","veil":"255,246,234"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'rustic-wedding');
